/**
 * Prepare Log Entry - Prepare structured log entry for PostgreSQL
 * Purpose: Receive log event from main workflow and prepare for insertion
 * Input: Complete log object from Execute Workflow Trigger
 * Output: Structured log entry ready for PostgreSQL
 * 
 * Contract:
 * - request_id: UUID (required)
 * - created_at: ISO timestamp (required) - passed from main workflow to ensure chronological order
 * - workflow_name: string (required)
 * - workflow_version: string (optional)
 * - stage: string (required)
 * - event_type: string (optional)
 * - level: 'INFO' | 'WARNING' | 'ERROR' (default: 'INFO')
 * - status: 'SUCCESS' | 'FAILED' | 'IN_PROGRESS' (default: 'IN_PROGRESS')
 * - chat_id: string (optional)
 * - user_id: string (optional)
 * - input_url: string (optional)
 * - duration_ms: number (optional)
 * - message: string (optional)
 * - error_code: string (optional)
 * - error_message: string (optional)
 * - details: object (optional, default: {})
 */
const input = $input.all()[0].json;

// Validate required fields
if (!input.request_id) {
  throw new Error('request_id is required');
}
if (!input.created_at) {
  throw new Error('created_at is required');
}
if (!input.workflow_name) {
  throw new Error('workflow_name is required');
}
if (!input.stage) {
  throw new Error('stage is required');
}

// Prepare log entry with defaults
const logEntry = {
  request_id: input.request_id,
  created_at: input.created_at,
  workflow_name: input.workflow_name,
  workflow_version: input.workflow_version || null,
  stage: input.stage,
  event_type: input.event_type || null,
  level: input.level || 'INFO',
  status: input.status || 'IN_PROGRESS',
  chat_id: input.chat_id || null,
  user_id: input.user_id || null,
  input_url: input.input_url || null,
  duration_ms: input.duration_ms || null,
  message: input.message || null,
  error_code: input.error_code || null,
  error_message: input.error_message || null,
  details: input.details || {}
};

// Log for debugging
console.log('[Log Writer] Processing log entry:');
console.log('[Log Writer] request_id:', logEntry.request_id);
console.log('[Log Writer] created_at:', logEntry.created_at);
console.log('[Log Writer] stage:', logEntry.stage);
console.log('[Log Writer] status:', logEntry.status);
console.log('[Log Writer] level:', logEntry.level);

return [{ json: logEntry }];

/**
 * Finalize Log Entry - Return success status
 * Purpose: Confirm log insertion and return result
 * Input: Inserted row from PostgreSQL
 * Output: Success confirmation with log ID
 */
const inserted = $input.all()[0].json;

console.log('[Log Writer] Log entry inserted successfully');
console.log('[Log Writer] ID:', inserted.id);
console.log('[Log Writer] created_at:', inserted.created_at);

return [{
  json: {
    success: true,
    log_id: inserted.id,
    request_id: inserted.request_id,
    created_at: inserted.created_at
  }
}];
